// Resuming a run after a crash: which steps still need to run (DESIGN.md §"Recovery").
// `events` is the append-only step log. Every step is idempotent, so the planner only has to decide what is safe
// to run again — it must never hand back a step that already finished.

/** One step of a run's plan. */
export interface PlanStep {
  key: string;
  dependsOn: string[];
}

export type StepStatus = "started" | "done" | "failed";

/** One line of the step log. */
export interface StepEvent {
  key: string;
  status: StepStatus;
}

/** A step that has failed this many times is excluded; so are the steps that depend on it. */
export const MAX_FAILURES = 3;

interface StepState {
  /** The status of the last event for the step, or null if it never ran. */
  status: StepStatus | null;
  failures: number;
}

/** Folds the log into one state per step. The last event wins, so a re-run that crashes reads as unfinished. */
function states(events: StepEvent[]): Map<string, StepState> {
  const byKey = new Map<string, StepState>();
  for (const e of events) {
    const s = byKey.get(e.key) ?? { status: null, failures: 0 };
    s.status = e.status;
    if (e.status === "failed") s.failures++;
    byKey.set(e.key, s);
  }
  return byKey;
}

/**
 * The keys to run next: in plan order, the steps whose dependencies are all done and which are not done
 * themselves. A step that started but did not finish is returned again, and so is a failed step — until it has
 * failed `MAX_FAILURES` times, after which it and its dependents are left out.
 */
export function nextSteps(plan: { steps: PlanStep[] }, events: StepEvent[]): string[] {
  const state = states(events);
  // A step with too many failures never counts as done, so its dependents can never become ready either.
  const excluded = new Set<string>();
  const done = new Set<string>();
  for (const [key, s] of state) {
    if (s.failures >= MAX_FAILURES) excluded.add(key);
    else if (s.status === "done") done.add(key);
  }

  const ready: string[] = [];
  for (const step of plan.steps) {
    if (done.has(step.key) || excluded.has(step.key)) continue;
    // A dependency that is missing from the plan, unfinished or excluded is not done: the step is not ready.
    if (step.dependsOn.every((dep) => done.has(dep))) ready.push(step.key);
  }
  return ready;
}

